stage_a_raw:
{
  "decisions": [
    {
      "decision": "domain_of_nurse_counts",
      "evidence": "\"Ignore the integrality constraints for now (i.e., we allow “half” nurse if necessary).\"",
      "options": [
        "NonNegativeReals",
        "NonNegativeIntegers",
        "Binary"
      ],
      "plausibility": [
        0.9,
        0.08,
        0.02
      ],
      "majority_option": "NonNegativeReals"
    },
    {
      "decision": "weekly_cyclic_vs_linear_horizon",
      "evidence": "\"Every nurse works 5 days in a row.\" / \"make a weekly night shift schedule\"",
      "options": [
        "Cyclic weekly horizon: a block starting on day s covers days (t-s) mod 7 in {0,...,4}",
        "Linear horizon: a block starting on day s covers days s..s+4 only, with no wrap-around"
      ],
      "plausibility": [
        0.6,
        0.4
      ],
      "majority_option": "Cyclic weekly horizon: a block starting on day s covers days (t-s) mod 7 in {0,...,4}"
    },
    {
      "decision": "start_day_set",
      "evidence": "\"Every nurse works 5 days in a row.\"",
      "options": [
        "Starts allowed on all 7 days (1..7)",
        "Starts allowed only on days 1..3 so blocks stay within the week"
      ],
      "plausibility": [
        0.85,
        0.15
      ],
      "majority_option": "Starts allowed on all 7 days (1..7)"
    },
    {
      "decision": "objective_quantity",
      "evidence": "\"minimize the total number of nurses used\"",
      "options": [
        "Minimize sum of nurses started (total nurses employed)",
        "Minimize sum of nurse-days worked (total shifts)"
      ],
      "plausibility": [
        0.9,
        0.1
      ],
      "majority_option": "Minimize sum of nurses started (total nurses employed)"
    },
    {
      "decision": "coverage_constraint_direction",
      "evidence": "\"meeting all demand\" / \"The demand for the night shift on day j is dj\"",
      "options": [
        ">= demand[t] (at least demand covered)",
        "= demand[t] (exactly demand covered)"
      ],
      "plausibility": [
        0.85,
        0.15
      ],
      "majority_option": ">= demand[t] (at least demand covered)"
    },
    {
      "decision": "answer_rounding_scale",
      "evidence": "\"Provide your answer rounded to the nearest integer.\"",
      "options": [
        "Round the LP objective (total nurses) to nearest integer",
        "Round each fractional nurse count first, then sum"
      ],
      "plausibility": [
        0.9,
        0.1
      ],
      "majority_option": "Round the LP objective (total nurses) to nearest integer"
    }
  ]
}
